//! Module-level references for the bar-code types without a usable image decoder, from encoders and
//! tables that are independent of the ones BurnBurn uses (W2-L5d):
//!
//! - `fixtures/barcode-bwipp.txt`: `bwipp-rs` 0.1.1 (a port of the BWIPP reference), generated by
//!   `research/barcode-reference`; used for Industrial/IATA 2 of 5, Plessey, PDF417, PDF417 Compact and
//!   MicroPDF417.
//! - `qrcode-generator` 6.1.2 (a second, separate Micro QR / rMQR encoder), called live.
//! - `fixtures/fiducial-reference.txt`: the official AprilTag C sources (code words, bit positions and the
//!   drawing algorithm of `apriltag_to_image`) and the OpenCV 7x7 dictionary as extracted by `locus-core`.
//! - one marker image drawn by OpenCV 4.13 (`cv2.aruco.generateImageMarker`), copied from the ground truth of
//!   the crate `calib-targets-aruco` (`tests/opencv_ground_truth.rs`).

#![allow(clippy::unwrap_used, clippy::panic)]

use burnburn_generators::{EncodedSymbol, SymbolLayout, Symbology, SymbologyParams, encode_symbol};
use qrcode_generator as qg;

fn params() -> SymbologyParams {
    SymbologyParams { height_mm: 10.0, ..SymbologyParams::new(0.4, 0.1) }
}

fn matrix(sym: &EncodedSymbol) -> (usize, usize, &Vec<bool>) {
    match &sym.layout {
        SymbolLayout::Matrix { width, height, modules } => (*width, *height, modules),
        other => panic!("not a matrix: {other:?}"),
    }
}

fn rows_of(sym: &EncodedSymbol) -> Vec<String> {
    let (w, h, m) = matrix(sym);
    (0..h).map(|r| (0..w).map(|c| if m[r * w + c] { '1' } else { '0' }).collect()).collect()
}

// ---------------------------------------------------------------------------------------------
// BWIPP fixtures
// ---------------------------------------------------------------------------------------------

struct Case {
    name: String,
    options: Vec<(String, String)>,
    payload: String,
    linear: Option<Vec<u32>>,
    rows: Vec<String>,
}

fn cases() -> Vec<Case> {
    let text = include_str!("fixtures/barcode-bwipp.txt");
    let mut out = Vec::new();
    let mut current: Option<Case> = None;
    for line in text.lines() {
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        if let Some(rest) = line.strip_prefix("case ") {
            let mut parts = rest.split(' ');
            let name = parts.next().unwrap().to_string();
            let mut options = Vec::new();
            let mut payload = String::new();
            for p in parts {
                match p.split_once('=') {
                    Some((k, v)) => options.push((k.to_string(), v.to_string())),
                    None => {
                        payload = (0..p.len() / 2)
                            .map(|i| u8::from_str_radix(&p[2 * i..2 * i + 2], 16).unwrap() as char)
                            .collect()
                    }
                }
            }
            current = Some(Case { name, options, payload, linear: None, rows: Vec::new() });
        } else if line == "end" {
            out.push(current.take().unwrap());
        } else if let Some(widths) = line.strip_prefix("L ") {
            current.as_mut().unwrap().linear = Some(widths.split(' ').map(|w| w.parse().unwrap()).collect());
        } else {
            current.as_mut().unwrap().rows.push(line.to_string());
        }
    }
    out
}

fn symbology_of(name: &str) -> Symbology {
    Symbology::from_stable_name(name).unwrap_or_else(|| panic!("fixture for unknown symbology {name}"))
}

/// Narrow/wide class of every element: wider than the narrowest element of its own colour.
fn classes(widths: &[u32]) -> String {
    let min = |skip: usize| widths.iter().skip(skip).step_by(2).copied().min().unwrap();
    let (min_bar, min_space) = (min(0), min(1));
    widths
        .iter()
        .enumerate()
        .map(|(i, &w)| if w > if i % 2 == 0 { min_bar } else { min_space } { 'W' } else { 'n' })
        .collect()
}

fn our_widths(sym: &EncodedSymbol) -> Vec<u32> {
    match &sym.layout {
        SymbolLayout::Linear { widths } => widths.iter().map(|&w| u32::from(w)).collect(),
        other => panic!("not linear: {other:?}"),
    }
}

#[test]
fn bwipp_fixtures_are_present_for_every_reference_symbology() {
    let all = cases();
    for name in ["two_of_five_industrial", "two_of_five_iata", "plessey", "pdf417", "pdf417_compact", "pdf417_micro"] {
        assert!(all.iter().filter(|c| c.name == name).count() >= 3, "fixtures for {name}");
    }
}

#[test]
fn two_of_five_and_plessey_match_the_bwipp_element_pattern() {
    // The two encoders draw wide elements at different ratios (BWIPP: 3:1 bars, 4:2 spaces for Plessey);
    // the narrow/wide sequence of every element is the symbology's actual content.
    let mut checked = 0;
    for c in cases().iter().filter(|c| c.linear.is_some()) {
        let sym = encode_symbol(symbology_of(&c.name), &c.payload, &params()).unwrap();
        let theirs = c.linear.clone().unwrap();
        let ours = our_widths(&sym);
        assert_eq!(ours.len(), theirs.len(), "{} {:?}: element count", c.name, c.payload);
        assert_eq!(classes(&ours), classes(&theirs), "{} {:?}", c.name, c.payload);
        checked += 1;
    }
    assert!(checked >= 15, "{checked} linear reference cases");
}

#[test]
fn pdf417_family_matches_the_bwipp_modules() {
    let mut checked = 0;
    for c in cases().iter().filter(|c| c.linear.is_none()) {
        let mut p = params();
        for (k, v) in &c.options {
            match k.as_str() {
                "eclevel" => p.ecc_step = Some(v.parse().unwrap()),
                "columns" => p.columns = Some(v.parse().unwrap()),
                other => panic!("unknown option {other}"),
            }
        }
        let sym = encode_symbol(symbology_of(&c.name), &c.payload, &p).unwrap();
        let ours = rows_of(&sym);
        // PDF417 draws every codeword row on several identical module rows (row height); BWIPP gives one line.
        let repeat = ours.len() / c.rows.len();
        assert!(
            repeat >= 1 && ours.len().is_multiple_of(c.rows.len()),
            "{} {:?}: {} vs {} rows",
            c.name,
            c.payload,
            ours.len(),
            c.rows.len()
        );
        for (i, want) in c.rows.iter().enumerate() {
            for k in 0..repeat {
                assert_eq!(&ours[i * repeat + k], want, "{} {:?}: row {i} (copy {k})", c.name, c.payload);
            }
        }
        checked += 1;
    }
    assert!(checked >= 12, "{checked} matrix reference cases");
}

// ---------------------------------------------------------------------------------------------
// Micro QR and rMQR against a second encoder
// ---------------------------------------------------------------------------------------------

#[test]
fn micro_qr_matches_a_second_encoder_module_for_module() {
    let steps = [
        (0u8, qg::micro::ErrorCorrection::DetectionOnly),
        (1, qg::micro::ErrorCorrection::Low),
        (2, qg::micro::ErrorCorrection::Medium),
        (3, qg::micro::ErrorCorrection::Quartile),
    ];
    let texts = [
        "1",
        "12345",
        "01234567",
        "0123456789",
        "9876543210987654",
        "HELLO",
        "AB12",
        "ABCDEFGHIJ",
        "A1B2C3D4E5F6",
        "hello",
        "Hello World!",
        "https://a.b",
        "burnburn",
        "Micro QR 1",
    ];
    let (mut compared, mut refused) = (0, 0);
    for text in texts {
        for (step, level) in steps {
            let mut p = params();
            p.ecc_step = Some(step);
            let ours = encode_symbol(Symbology::QrMicro, text, &p);
            let theirs = qg::micro::Encoder::new(level).boost_error_correction(false).encode_text(text);
            match (ours, theirs) {
                (Ok(ours), Ok(theirs)) => {
                    let (w, h, m) = matrix(&ours);
                    assert_eq!((w, h), (theirs.width(), theirs.height()), "{text:?} step {step}");
                    assert_eq!(m.as_slice(), theirs.modules(), "{text:?} step {step}");
                    compared += 1;
                }
                (Err(_), Err(_)) => refused += 1,
                (a, b) => panic!("{text:?} step {step}: disagree on feasibility: {a:?} vs {b:?}"),
            }
        }
    }
    assert!(compared >= 30, "{compared} micro symbols compared ({refused} refused by both)");
}

#[test]
fn rmqr_matches_a_second_encoder_module_for_module() {
    let steps = [(0u8, qg::rmqr::ErrorCorrection::Medium), (1, qg::rmqr::ErrorCorrection::High)];
    let texts = [
        "1",
        "12345",
        "9876543210987654321",
        "HELLO",
        "AB12",
        "hello",
        "https://example.com/abc",
        "The quick brown fox jumps",
        "RMQR7X43",
        "0123456789012345678901234567890123456789",
    ];
    let mut compared = 0;
    for text in texts {
        for (step, level) in steps {
            let mut p = params();
            p.ecc_step = Some(step);
            let ours = encode_symbol(Symbology::QrMicroRect, text, &p).unwrap();
            let theirs = qg::rmqr::Encoder::new(level).boost_error_correction(false).encode_text(text).unwrap();
            let (w, h, m) = matrix(&ours);
            assert_eq!((w, h), (theirs.width(), theirs.height()), "{text:?} step {step}");
            assert_eq!(m.as_slice(), theirs.modules(), "{text:?} step {step}");
            compared += 1;
        }
    }
    assert_eq!(compared, 20);
}

// ---------------------------------------------------------------------------------------------
// fiducial markers
// ---------------------------------------------------------------------------------------------

struct AprilFamily {
    name: String,
    width_at_border: usize,
    total_width: usize,
    nbits: usize,
    bit_x: Vec<usize>,
    bit_y: Vec<usize>,
    codes: Vec<u64>,
}

struct Reference {
    april: Vec<AprilFamily>,
    opencv_7x7: Vec<u64>,
}

fn hex(token: &str) -> u64 {
    u64::from_str_radix(token, 16).unwrap()
}

fn reference() -> Reference {
    let text = include_str!("fixtures/fiducial-reference.txt");
    let mut april = Vec::new();
    let mut opencv_7x7 = Vec::new();
    let mut fam: Option<AprilFamily> = None;
    let mut in_opencv = false;
    for line in text.lines() {
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let mut t = line.split(' ');
        match t.next().unwrap() {
            "apriltag" => {
                let name = t.next().unwrap().to_string();
                let kv: Vec<usize> = t.map(|x| x.split_once('=').unwrap().1.parse().unwrap()).collect();
                fam = Some(AprilFamily {
                    name,
                    width_at_border: kv[0],
                    total_width: kv[1],
                    nbits: kv[2],
                    bit_x: vec![],
                    bit_y: vec![],
                    codes: vec![],
                });
            }
            "opencv_7x7_100" => in_opencv = true,
            "bit_x" => fam.as_mut().unwrap().bit_x = t.map(|x| x.parse().unwrap()).collect(),
            "bit_y" => fam.as_mut().unwrap().bit_y = t.map(|x| x.parse().unwrap()).collect(),
            "codes" => {
                let codes = t.map(hex);
                if in_opencv {
                    opencv_7x7.extend(codes);
                } else {
                    fam.as_mut().unwrap().codes.extend(codes);
                }
            }
            "end" => {
                if let Some(f) = fam.take() {
                    april.push(f);
                }
                in_opencv = false;
            }
            other => panic!("unknown fixture line {other}"),
        }
    }
    Reference { april, opencv_7x7 }
}

/// `apriltag_to_image` of the official sources: cells start black, a set code bit makes its cell white.
/// Returns the `width_at_border` square (black border ring included) as rows of '#' (black) and '.'.
fn official_tag(f: &AprilFamily, id: usize) -> Vec<String> {
    let n = f.width_at_border;
    let mut cells = vec![vec![true; n]; n];
    for i in 0..f.nbits {
        if f.codes[id] & (1u64 << (f.nbits - i - 1)) != 0 {
            cells[f.bit_y[i]][f.bit_x[i]] = false;
        }
    }
    cells.iter().map(|r| r.iter().map(|&b| if b { '#' } else { '.' }).collect()).collect()
}

fn marker_rows(sym: &EncodedSymbol) -> Vec<String> {
    let (w, h, m) = matrix(sym);
    (0..h).map(|r| (0..w).map(|c| if m[r * w + c] { '#' } else { '.' }).collect()).collect()
}

fn apriltag_symbology(name: &str) -> Symbology {
    match name {
        "16h5" => Symbology::AprilTag16h5,
        "25h9" => Symbology::AprilTag25h9,
        "36h10" => Symbology::AprilTag36h10,
        "36h11" => Symbology::AprilTag36h11,
        other => panic!("unknown family {other}"),
    }
}

#[test]
fn every_apriltag_id_matches_the_official_image_of_the_reference_sources() {
    let reference = reference();
    assert_eq!(reference.april.len(), 4);
    let mut total = 0;
    for f in &reference.april {
        assert_eq!(
            f.width_at_border,
            f.total_width - 2,
            "{}: the standard families have a one-cell white border",
            f.name
        );
        let sym = apriltag_symbology(&f.name);
        assert_eq!(f.codes.len(), [30, 35, 2320, 587][reference.april.iter().position(|x| x.name == f.name).unwrap()]);
        for id in 0..f.codes.len() {
            let ours = encode_symbol(sym, &id.to_string(), &params()).unwrap();
            assert_eq!(marker_rows(&ours), official_tag(f, id), "{} id {id}", f.name);
            total += 1;
        }
    }
    assert_eq!(total, 30 + 35 + 2320 + 587);
}

#[test]
fn apriltag_orientation_is_the_official_one_which_is_opencvs_turned_by_180_degrees() {
    // OpenCV 4.13 `generateImageMarker(DICT_APRILTAG_36h11, 0, ...)`, inner 6x6 cells ('#' black), from the
    // ground truth of calib-targets-aruco; the border ring is black.
    let opencv_inner = ["##.###", "#..#.#", "###.#.", "###..#", ".#...#", ".#.#.."];
    let ours = marker_rows(&encode_symbol(Symbology::AprilTag36h11, "0", &params()).unwrap());
    let inner: Vec<String> = ours[1..7].iter().map(|r| r[1..7].to_string()).collect();
    let turned: Vec<String> = opencv_inner.iter().rev().map(|r| r.chars().rev().collect()).collect();
    assert_eq!(inner, turned);
    assert_ne!(inner, opencv_inner.iter().map(ToString::to_string).collect::<Vec<_>>(), "not OpenCV's own orientation");
}

#[test]
fn opencv_7x7_ids_match_the_opencv_dictionary_as_extracted_by_locus_core() {
    let reference = reference();
    assert_eq!(reference.opencv_7x7.len(), 100);
    for (id, &code) in reference.opencv_7x7.iter().enumerate() {
        let sym = encode_symbol(Symbology::ArucoOpenCv7x7, &id.to_string(), &params()).unwrap();
        let (w, _, m) = matrix(&sym);
        assert_eq!(w, 9);
        for r in 0..7 {
            for c in 0..7 {
                // OpenCV polarity: a set bit is a white cell; row-major, bit 0 = top-left.
                let white = (code >> (r * 7 + c)) & 1 == 1;
                assert_eq!(m[(r + 1) * w + c + 1], !white, "id {id} cell {r},{c}");
            }
        }
    }
}
